EXPECTED_SHA256 = '4729c9d7fa06e6d69f39d7c4d73ac387fd14642880e94ad9fc134a7553a4bc54'

def main():
    archive = zlib.decompress(base64.b85decode(ENCODED_ARCHIVE.encode('ascii')))
    if hashlib.sha256(archive).hexdigest() != EXPECTED_SHA256:
        raise ValueError('Source file failed integrity check')
    destination = Path.cwd().resolve()
    with zipfile.ZipFile(BytesIO(archive)) as zf:
        for item in zf.infolist():
            target = (destination / item.filename).resolve()
            if not target.is_relative_to(destination):
                raise ValueError('Unsafe file path in source data')
            if item.is_dir():
                target.mkdir(parents=True, exist_ok=True)
            else:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(zf.read(item))
    print('Created:', destination / 'questionforge-extension')
    print('Next: Chrome -> chrome://extensions -> Developer mode -> Load unpacked -> select questionforge-extension')

if __name__ == '__main__':
    main()
